# New film assets are sibling copies; old V32.70 videos stay frozen.
old=P/'motion/life-purpose-v1';new=P/'motion/life-purpose-v2';shutil.copytree(old,new,dirs_exist_ok=True)
out=P/'assets/life-purpose/v32-72';out.mkdir(parents=True,exist_ok=True)
for file in (P/'assets/life-purpose/v32-70').iterdir():
 if file.is_file() and file.suffix not in ['.mp4'] and not (out/file.name).exists():shutil.copy2(file,out/file.name)
